//! Purpose: the one-byte enums stored in accounts and passed in instruction data, with their
//!          checked conversion from a raw byte.
//! Version: 0.0.2
//! Sprint: 02 (pot core on Pinocchio)
//!
//! Stored as `u8` in the layouts and tagged by position, as Borsh would: a new variant is
//! appended, never inserted or reordered (CLAUDE.md). Each enum is written out in full, not
//! generated by a macro, because shank-cli reads the source to build the IDL.

use shank::ShankType;

use crate::error::BrotError;

/// The five kinds of on-chain reading a campaign can ask about (TP section 3.4.8). Closed on
/// purpose: there is no generic reader.
#[derive(ShankType, Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
pub enum ReaderKind {
    PriceTouch = 0,
    SupplyAtMost = 1,
    DammV2LockedAtLeast = 2,
    StakePoolTvlAtLeast = 3,
    StakeAtLeast = 4,
}

/// Where a campaign is in its life (TP section 3.4.2). "Closed" is not stored: it comes from the
/// clock and the reader.
#[derive(ShankType, Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
pub enum Status {
    Open = 0,
    InReview = 1,
    Contested = 2,
    Settling = 3,
    Settled = 4,
}

/// The answer read for a campaign. `Unresolved` until `resolve_campaign` (Sprint 03).
#[derive(ShankType, Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
pub enum Outcome {
    Unresolved = 0,
    Yes = 1,
    No = 2,
    Void = 3,
}

/// How a finalized campaign pays (TP section 3.4.16). `Unset` until finalize (Sprint 04).
#[derive(ShankType, Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
pub enum SettleMode {
    Unset = 0,
    Split = 1,
    OneSided = 2,
    Refund = 3,
}

/// Why a campaign was voided (TP section 3.4.7). The reason decides where the held opening fee
/// goes, so every void records one.
#[derive(ShankType, Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
pub enum VoidReason {
    None = 0,
    MissedWindow = 1,
    UnreadableAccount = 2,
    StaleFeed = 3,
    TeamHouseFailure = 4,
    TeamOutsideCause = 5,
}

/// The contest stage of a campaign (TP section 3.4.7, Sprints 04 and 14).
#[derive(ShankType, Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
pub enum ContestStage {
    None = 0,
    Stage1 = 1,
    Stage2 = 2,
}

/// The pause (TP section 3.4.9). `EntriesHalted` stops joins and openings, never payouts.
#[derive(ShankType, Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
pub enum OperatingLevel {
    Normal = 0,
    EntriesHalted = 1,
}

/// The side an entry joins.
#[derive(ShankType, Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
pub enum Side {
    Yes = 0,
    No = 1,
}

/// Which way a price campaign's target is touched: YES when the price reaches the target from
/// below (`Above`) or from above (`Below`).
#[derive(ShankType, Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
pub enum Direction {
    Above = 0,
    Below = 1,
}

/// What a `ConfigChanged` event reports as changed.
#[derive(ShankType, Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
pub enum ConfigChange {
    Team = 0,
    CreationParams = 1,
    FeeRecipient = 2,
    PendingAdmin = 3,
    Admin = 4,
}

/// `TryFrom<u8>` for each enum: a byte that is not a variant is refused with the given error.
macro_rules! try_from_u8 {
    ($($ty:ident => $err:expr => [$($variant:ident),+]);+ $(;)?) => {
        $(
            impl TryFrom<u8> for $ty {
                type Error = BrotError;

                fn try_from(byte: u8) -> Result<Self, BrotError> {
                    $(
                        if byte == $ty::$variant as u8 {
                            return Ok($ty::$variant);
                        }
                    )+
                    Err($err)
                }
            }
        )+
    };
}

try_from_u8! {
    ReaderKind => BrotError::UnknownReaderKind =>
        [PriceTouch, SupplyAtMost, DammV2LockedAtLeast, StakePoolTvlAtLeast, StakeAtLeast];
    Status => BrotError::BadAccountData => [Open, InReview, Contested, Settling, Settled];
    Outcome => BrotError::BadAccountData => [Unresolved, Yes, No, Void];
    SettleMode => BrotError::BadAccountData => [Unset, Split, OneSided, Refund];
    VoidReason => BrotError::BadAccountData =>
        [None, MissedWindow, UnreadableAccount, StaleFeed, TeamHouseFailure, TeamOutsideCause];
    ContestStage => BrotError::BadAccountData => [None, Stage1, Stage2];
    OperatingLevel => BrotError::BadAccountData => [Normal, EntriesHalted];
    Side => BrotError::InvalidSide => [Yes, No];
    Direction => BrotError::InvalidDirection => [Above, Below];
    ConfigChange => BrotError::BadAccountData =>
        [Team, CreationParams, FeeRecipient, PendingAdmin, Admin];
}
